// Fee changes and receipt voids need an Administrator.
//
// The Cashier handles money coming in. Changing what a student owes, or cancelling a receipt, could hide missing
// money, so a Cashier cannot do either alone: they file a request with a reason, and an Administrator approves or
// rejects it. Nobody can approve their own request, every step is written to the audit log, and receipt numbers are
// always generated by the system.
import { db, transaction } from './db.js'
import { HttpError, audit, balanceFor, currentTerm, notify, notifyRoles, nowIso, peso } from './util.js'

// Keep one "Due" row equal to what a student still owes.
export async function syncDue(studentId) {
  const term = await currentTerm()
  const { balance } = await balanceFor(studentId)
  const previous = (await db.prepare("SELECT MIN(due_on) AS d FROM payments WHERE student_id = ? AND term_id = ? AND status = 'Due'").get(studentId, term.id))?.d
  await db.prepare("DELETE FROM payments WHERE student_id = ? AND term_id = ? AND status = 'Due'").run(studentId, term.id)
  if (balance > 0) {
    const fallback = new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10)
    await db.prepare("INSERT INTO payments (student_id, term_id, due_on, amount, status) VALUES (?,?,?,?, 'Due')").run(studentId, term.id, previous ?? fallback, balance)
  }
}

export function feeFields(body) {
  const name = String(body?.name ?? '').trim().slice(0, 60)
  const amount = Number(body?.amount)
  if (name.length < 2) throw new HttpError(400, 'Enter the fee name.')
  if (!Number.isFinite(amount) || amount <= 0 || amount > 1000000) throw new HttpError(400, 'Enter an amount greater than zero.')
  return { name, amount: Math.round(amount * 100) / 100 }
}

export const CHANGE_LABEL = { 'fee.add': 'Add a fee', 'fee.update': 'Change a fee', 'fee.delete': 'Remove a fee', 'payment.void': 'Void a receipt' }

const loginOf = async (id) => (await db.prepare('SELECT login_id FROM users WHERE id = ?').get(id))?.login_id
const nameOf = async (id) => (await db.prepare('SELECT name FROM users WHERE id = ?').get(id))?.name ?? 'a cashier'

// A Cashier asks for a change. Nothing changes until an Administrator approves it.
export async function requestChange(user, { kind, studentId, targetId = null, name = null, amount = null, summary, reason }) {
  const why = String(reason ?? '').trim().slice(0, 300)
  if (why.length < 5) throw new HttpError(400, 'Give a reason in a few words so the Administrator can decide.')
  if (targetId != null && (await db.prepare("SELECT 1 FROM change_requests WHERE kind = ? AND target_id = ? AND status = 'Pending'").get(kind, targetId)))
    throw new HttpError(409, 'A request for this is already waiting for the Administrator.')
  const row = await db
    .prepare(
      `INSERT INTO change_requests (kind, student_id, target_id, name, amount, summary, reason, requested_by, requested_at)
       VALUES (?,?,?,?,?,?,?,?,?) RETURNING id`,
    )
    .get(kind, studentId, targetId, name, amount, summary, why, user.id, nowIso())
  await audit(user, 'change.request', 'student', await loginOf(studentId), `${summary} — ${why}`)
  await notifyRoles('admin', `${user.name} asks for approval: ${summary}.`, '/admin/approvals')
  return row.id
}

// The list shown to the Administrator (to decide) and to the Cashier (to follow up).
export async function listChanges({ status = 'all', studentId = null } = {}) {
  const where = []
  const params = []
  if (status !== 'all') {
    where.push('c.status = ?')
    params.push(status)
  }
  if (studentId != null) {
    where.push('c.student_id = ?')
    params.push(studentId)
  }
  const rows = await db
    .prepare(
      `SELECT c.id, c.kind, c.target_id AS targetId, c.summary, c.reason, c.status, c.requested_at AS requestedAt, c.decided_at AS decidedAt, c.decision_note AS decisionNote,
              u.name AS studentName, u.login_id AS studentNo, rq.name AS requestedBy, dc.name AS decidedBy
       FROM change_requests c JOIN users u ON u.id = c.student_id
       LEFT JOIN users rq ON rq.id = c.requested_by LEFT JOIN users dc ON dc.id = c.decided_by
       ${where.length ? 'WHERE ' + where.join(' AND ') : ''}
       ORDER BY (c.status = 'Pending') DESC, c.requested_at DESC, c.id DESC LIMIT 200`,
    )
    .all(...params)
  return rows.map((r) => ({ ...r, label: CHANGE_LABEL[r.kind] }))
}

async function applyChange(r, admin) {
  const student = await loginOf(r.student_id)
  const by = `requested by ${await nameOf(r.requested_by)}, approved by ${admin.name}`
  if (r.kind === 'fee.add') {
    await db.prepare('INSERT INTO fees (student_id, term_id, name, amount) VALUES (?,?,?,?)').run(r.student_id, (await currentTerm()).id, r.name, r.amount)
    await audit(admin, 'fee.add', 'student', student, `${r.name} ${peso(r.amount)} (${by})`)
  } else if (r.kind === 'fee.update' || r.kind === 'fee.delete') {
    const fee = await db.prepare('SELECT * FROM fees WHERE id = ?').get(r.target_id)
    if (!fee) throw new HttpError(409, 'That fee no longer exists, so this request cannot be applied. Reject it.')
    if (r.kind === 'fee.update') {
      await db.prepare('UPDATE fees SET name = ?, amount = ? WHERE id = ?').run(r.name, r.amount, fee.id)
      await audit(admin, 'fee.update', 'student', student, `${fee.name} ${peso(fee.amount)} → ${r.name} ${peso(r.amount)} (${by})`)
    } else {
      await db.prepare('DELETE FROM fees WHERE id = ?').run(fee.id)
      await audit(admin, 'fee.delete', 'student', student, `${fee.name} ${peso(fee.amount)} (${by})`)
    }
  } else if (r.kind === 'payment.void') {
    const payment = await db.prepare("SELECT * FROM payments WHERE id = ? AND status = 'Paid'").get(r.target_id)
    if (!payment) throw new HttpError(409, 'That receipt is already void or no longer exists. Reject this request.')
    await db.prepare("UPDATE payments SET status = 'Void', void_reason = ? WHERE id = ?").run(r.reason, payment.id)
    await audit(admin, 'payment.void', 'payment', payment.reference, `${peso(payment.amount)} for ${student} — ${r.reason} (${by})`)
    await notify(payment.student_id, `Receipt ${payment.reference} (${peso(payment.amount)}) was voided: ${r.reason}`, '/account')
  } else throw new HttpError(400, 'Unknown request type.')
  await syncDue(r.student_id)
}

export async function decideChange(admin, id, decision, note) {
  const r = await db.prepare('SELECT * FROM change_requests WHERE id = ?').get(id)
  if (!r) throw new HttpError(404, 'Request not found.')
  if (r.status !== 'Pending') throw new HttpError(409, 'This request was already decided.')
  const remark = String(note ?? '').trim().slice(0, 300)
  if (decision !== 'approve' && decision !== 'reject') throw new HttpError(400, 'Choose approve or reject.')
  if (decision === 'reject' && remark.length < 3) throw new HttpError(400, 'Say why you are rejecting it.')

  await transaction(async () => {
    // claim the request first, so two Administrators cannot both apply it
    const claimed = await db
      .prepare("UPDATE change_requests SET status = ?, decided_by = ?, decided_at = ?, decision_note = ? WHERE id = ? AND status = 'Pending'")
      .run(decision === 'approve' ? 'Approved' : 'Rejected', admin.id, nowIso(), remark || null, r.id)
    if (!claimed.changes) throw new HttpError(409, 'This request was already decided.')
    if (decision === 'approve') await applyChange(r, admin)
  })
  await audit(admin, decision === 'approve' ? 'change.approve' : 'change.reject', 'student', await loginOf(r.student_id), `${r.summary}${remark ? ` — ${remark}` : ''}`)
  if (r.requested_by)
    await notify(r.requested_by, `${decision === 'approve' ? 'Approved' : 'Rejected'}: ${r.summary}${remark ? ` (${remark})` : ''}`, '/cashier/changes')
}
